"""New small trends, target tracks and operational time maps."""
from write_elements import write as _write
def write(leaf,root,css,description,fixtures):
 css=css.replace('--od-','--onboard-docket-')
 _write(leaf,root,css,description,fixtures)
import sys

def author(k):
 if k=='sparkline':
  css='''/* Inferred from replica17 open figures and replica16 fine rules; miniature data, no scene. */
ROOT{container-type:size;container-name:od-spark;position:relative;anchor-scope:all;display:grid;grid-template-columns:repeat(var(--od-spark-n),minmax(0,1fr));grid-template-rows:minmax(0,1fr);align-self:center;block-size:min(100%,90px);padding-block:var(--stroke);min-width:0;min-height:0;color:var(--n-7);}ROOT>span{position:static;grid-column:var(--od-spark-i);grid-row:1;align-self:start;justify-self:center;width:0;height:0;margin-top:calc(100cqh*(1 - var(--v)/var(--max)));anchor-name:var(--od-spark-self)}ROOT>span::before{content:"";position:absolute;left:anchor(var(--od-spark-prev) center);right:anchor(var(--od-spark-self) center);top:calc(anchor(var(--od-spark-prev) center) - 100cqh);bottom:var(--stroke);background:currentColor;clip-path:polygon(0 calc(100cqh - 1px),100% calc(100% - 100cqh*var(--v)/var(--max) - 1px),100% calc(100% - 100cqh*var(--v)/var(--max) + 1px),0 calc(100cqh + 1px))}ROOT>span:first-child::before{display:none}ROOT.up{color:var(--good)}ROOT.down{color:var(--bad)}ROOT.bars>span{position:relative;align-self:end;width:68%;height:calc(100cqh*var(--v)/var(--max));margin:0;border-radius:999px 999px 0 0;background:currentColor}ROOT.bars>span::before{display:none}
'''
  for i in range(1,25):css+=f'ROOT:has(>span:nth-child({i}):last-child){{--od-spark-n:{i}}}ROOT>span:nth-child({i}){{--od-spark-i:{i};--od-spark-self:--od-s{i};--od-spark-prev:--od-s{i-1}}}'
  def row(bars=False):return '<div class="spark '+('bars'if bars else'up')+'" DATA style="--max:100">'+''.join('<span style="--v:'+str(v)+'"></span>'for v in ([38,46,59,55,68,76,71,89,94]if bars else[38,45,42,57,57,73,86]))+'</div>'
  write(k,'spark',css,'A thin miniature trend sits at the optical centre of its slot. Its complete interval chain uses actual point anchors, with a rounded-cap bar variant and semantic good/bad palette roles.',[('approval-trend','3x2',row()),('weekly-volume','3x2',row(True)),('declining-queue','3x2','<div class="spark down" DATA style="--max:100">'+''.join('<span style="--v:'+str(v)+'"></span>' for v in [86,78,81,59,59,43,36])+'</div>'),('zero-incidents','3x1','<div class="spark" DATA style="--max:1">'+''.join('<span style="--v:0"></span>' for _ in range(5))+'</div>')])
 elif k=='bullet':
  css='''/* Inferred from replica06 long capsules and replica17 bare figure labels. */
.bullets[data-el="onboard-docket-bullet"]{container-type:size;display:grid;grid-template-rows:repeat(var(--od-bullet-n),minmax(0,1fr));gap:var(--gap-sm);min-width:0;min-height:0;}.bullet[data-el="onboard-docket-bullet"]{container-type:size;container-name:od-bullet;position:relative;display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-rows:auto calc(var(--stroke)*14) auto;align-content:center;gap:calc(var(--gap-sm)/2);min-width:0;min-height:0;padding:0 var(--gap-sm);color:var(--ink)}.bullet[data-el="onboard-docket-bullet"]>.name,.bullet[data-el="onboard-docket-bullet"]>.fig{grid-row:1;margin:0;font-size:var(--type-16);font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track);overflow-wrap:anywhere}.bullet[data-el="onboard-docket-bullet"]>.fig{grid-column:2;font-size:var(--type-22);font-weight:var(--figure-weight);line-height:var(--figure-line);letter-spacing:var(--figure-track)}.bullet[data-el="onboard-docket-bullet"]>.note{grid-column:1 / -1;grid-row:3;margin:0;font-size:var(--type-12);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--n-7)}.bullet[data-el="onboard-docket-bullet"]::before{content:"";grid-column:1 / -1;grid-row:2;border-radius:999px;background:linear-gradient(to right,transparent calc(var(--target)*1% - 1px),var(--ink) calc(var(--target)*1% - 1px) calc(var(--target)*1% + 1px),transparent 0),linear-gradient(to right,var(--n-1) 0 calc(var(--low,35)*1%),var(--n-2) 0 calc(var(--high,70)*1%),var(--n-3) 0)}.bullet[data-el="onboard-docket-bullet"]::after{content:"";grid-column:1 / -1;grid-row:2;align-self:center;height:6px;border-radius:999px;width:calc(var(--v)*1%);background:var(--a1)}@container od-bullet (max-height:100px){.bullet[data-el="onboard-docket-bullet"]>.name{font-size:var(--type-14)}.bullet[data-el="onboard-docket-bullet"]>.fig{font-size:var(--type-18)}.bullet[data-el="onboard-docket-bullet"]>.note{display:none}}
'''
  for i in range(1,7):css+=f'.bullets[data-el="onboard-docket-bullet"]:has(>.bullet:nth-child({i}):last-child){{--od-bullet-n:{i}}}'
  def row(n):return '<div class="bullets" DATA>'+''.join('<div class="bullet" data-el="onboard-docket-bullet" style="--v:'+str(v)+';--target:'+str(t)+'"><p class="name">'+name+'</p><p class="fig">'+str(v)+'%</p><p class="note">점검 목표 '+str(t)+'%와 비교한 승인 집계</p></div>'for name,v,t in [('담당 조직 배정','73',85),('승인 근거 대조','86',90),('후속 조치 확인','61',75)][:n])+'</div>'
  write(k,'bullet',css,'A capsule track combines quiet qualitative bands, a narrow dark target marker and a slimmer actual fill. Name, actual figure and target note remain separate and readable.',[('three-targets','6x3',row(3)),('two-targets','4x3',row(2)),('single-long-bands','4x2','<div class="bullet" DATA style="--v:82;--target:88;--low:42;--high:73"><p class="name">상담 이관 사유 및 책임 조직 확인</p><p class="fig">82%</p><p class="note">승인 기록을 실제 접수 내용과 대조한 비율이며 최종 목표는 88%입니다.</p></div>')])
 elif k=='roadmap':
  css='''/* Inferred from replica16 ruled rows and replica06 capsule labels; durations stay proportional. */
ROOT{container-type:size;container-name:od-roadmap;display:grid;grid-template-rows:calc(var(--type-14)*2) repeat(var(--od-roadmap-n),minmax(0,1fr));gap:var(--gap-sm);min-width:0;min-height:0;color:var(--ink);}ROOT>.heads{display:grid;grid-template-columns:repeat(var(--cols),minmax(0,1fr));width:80%;justify-self:end;border-bottom:var(--stroke) solid var(--n-4)}ROOT>.heads>span{text-align:center;font-size:var(--type-14);font-weight:var(--label-weight);line-height:var(--label-line);letter-spacing:var(--label-track);overflow-wrap:anywhere}ROOT>.lane{container-type:size;position:relative;min-width:0;min-height:0;border-bottom:var(--stroke) solid var(--n-3)}ROOT>.lane>.name{position:absolute;left:0;top:50%;transform:translateY(-50%);width:18%;margin:0;font-size:var(--type-14);font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track);overflow-wrap:anywhere}ROOT>.lane>.bar{position:absolute;left:calc(20% + 80%*var(--from)/var(--cols));width:calc(80%*(var(--to) - var(--from))/var(--cols) - var(--gap-sm)/2);top:50%;transform:translateY(-50%);min-width:0;min-height:0;height:32px;border-radius:999px;display:flex;align-items:center;justify-content:center;padding:0 calc(var(--gap-sm)/2);background:var(--n-2);color:var(--ink)}ROOT>.lane>.bar>span{font-size:var(--type-14);font-weight:var(--body-weight);line-height:var(--label-line);letter-spacing:var(--body-track);text-align:center;overflow-wrap:anywhere}ROOT>.lane>.bar.on{background:var(--a1);color:var(--a1-on)}ROOT>.lane>.bar.tone-2{background:var(--a2);color:var(--a2-on)}ROOT>.lane>.mile{position:absolute;left:clamp(4px,calc(20% + 80%*var(--at)/var(--cols)),calc(100% - 4px));top:50%;width:0;height:0}ROOT>.lane>.mile::before{content:"";position:absolute;left:-4px;top:-4px;width:8px;height:8px;background:var(--a1-7);rotate:45deg}ROOT>.lane>.mile>span{position:absolute;top:calc(16px + var(--stroke)*2);left:0;transform:translateX(calc(-100%*var(--at)/var(--cols)));white-space:nowrap;font-size:var(--type-12);font-weight:var(--body-weight);line-height:var(--label-line);letter-spacing:var(--body-track);color:var(--ink)}@container od-roadmap (max-width:850px){ROOT>.lane>.bar>span,ROOT>.heads>span,ROOT>.lane>.name{font-size:var(--type-12)}}
'''
  for n in range(2,7):css+=f'ROOT:has(>.lane:nth-child({n+1}):last-child){{--od-roadmap-n:{n}}}'
  css+='ROOT>.lane>.bar.tone-1{background:var(--a1);color:var(--a1-on)}ROOT>.lane>.bar.tone-3{background:var(--a3);color:var(--a3-on)}ROOT>.lane>.bar.tone-4{background:var(--a4);color:var(--a4-on)}ROOT>.lane>.bar.tone-5{background:var(--n-7);color:var(--page)}ROOT>.lane>.bar.on{background:var(--a1);color:var(--a1-on)}@container(max-height:75px){ROOT>.lane>.mile{top:40%}ROOT>.lane>.mile>span{font-size:var(--type-10)}}'
  def row(alt=False):return '<div class="roadmap" DATA style="--cols:4"><div class="heads">'+''.join('<span>'+str(i+1)+'분기</span>'for i in range(4))+'</div>'+''.join('<div class="lane"><p class="name">'+name+'</p><div class="bar'+(' on' if i==1 else ' tone-2' if alt and i==3 else '')+'" style="--from:'+str(a)+';--to:'+str(b)+'"><span>'+text+'</span></div>'+('<div class="bar" style="--from:2;--to:3"><span>보완 대조</span></div>' if alt and i==0 else '')+('<div class="mile" style="--at:4"><span>최종 점검</span></div>' if i==2 else '')+'</div>'for i,(name,a,b,text) in enumerate([('상담 운영',0,2,'접수 기준 협의'),('승인 관리',1,3,'예외 요청 검토'),('품질 점검',2,4,'후속 기록 대조')]if not alt else[('운영 지원',0,1,'담당 배정'),('서비스 기획 및 승인 근거 관리',1,3,'현장 변경 내역 합의'),('품질 관리',2,4,'재발 위험 점검'),('문서 관리',0,4,'검토 기준 공유')]))+'</div>'
  write(k,'roadmap',css,'Ruled owner lanes contain rounded duration bars whose starts and lengths follow the supplied periods. A single accent span marks the priority work, keeping labels inside their own duration.',[('quarter-plan','8x4',row()),('review-plan','8x6',row(True))])
 elif k=='journey':
  css='''/* Inferred from replica15 joined operational stages and replica17 bare numeric rhythm. */
ROOT{container-type:size;container-name:od-journey;display:grid;grid-template-columns:repeat(var(--od-journey-n),minmax(0,1fr));gap:var(--gap-sm);min-width:0;min-height:0;color:var(--ink);}ROOT>.stage{position:relative;min-width:0;min-height:0;text-align:center}ROOT>.stage>.name{position:absolute;left:0;right:0;top:5%;margin:0;font-size:var(--type-18);font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track);overflow-wrap:anywhere}ROOT>.stage>.note{position:absolute;left:0;right:0;top:75%;margin:0;font-size:var(--type-14);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--n-7);overflow-wrap:anywhere}ROOT>.stage>.pain{position:absolute;left:0;right:0;bottom:0;margin:0;font-size:var(--type-12);font-weight:var(--body-weight);line-height:var(--label-line);letter-spacing:var(--body-track);color:var(--bad);overflow-wrap:anywhere}ROOT>.stage:not(:last-child)::before{content:"";position:absolute;left:50%;top:calc(65cqh - .25cqh*var(--mood));width:hypot(calc((100cqw + var(--gap-sm))/var(--od-journey-n)),calc(.25cqh*(var(--mood) - var(--next))));height:2px;transform-origin:0 50%;rotate:atan2(calc(.25cqh*(var(--mood) - var(--next))),calc((100cqw + var(--gap-sm))/var(--od-journey-n)));background:var(--n-6)}ROOT>.stage::after{content:"";position:absolute;left:calc(50% - 5px);top:calc(65cqh - .25cqh*var(--mood) - 5px);width:10px;height:10px;border-radius:50%;background:var(--page);border:2px solid var(--n-6)}ROOT>.stage.on::after{background:var(--a1);border-color:var(--a1)}@container od-journey (max-width:700px){ROOT>.stage>.name{font-size:var(--type-14)}ROOT>.stage>.note{font-size:var(--type-12)}}@container od-journey (max-height:320px){ROOT>.stage>.name{font-size:var(--type-14)}ROOT>.stage>.note{font-size:var(--type-12);line-height:var(--label-line)}ROOT>.stage>.pain{display:none}}
'''
  for n in range(3,8):css+=f'ROOT:has(>.stage:nth-child({n}):last-child){{--od-journey-n:{n}}}'
  def row(n):
   stages=[('요청 접수',64,'상담 채널에서 문의를 분류합니다.','안내 문구가 채널마다 다름'),('범위 확인',49,'담당 조직과 처리 범위를 맞춥니다.','이관 기준을 다시 확인함'),('승인 검토',73,'책임자가 변경 사유를 대조합니다.','예외 근거 보완이 필요함'),('처리 안내',86,'승인된 조치 결과를 전달합니다.',''),('후속 점검',79,'남은 문의와 재발 위험을 살핍니다.',''),('개선 공유',91,'다음 배포의 승인 조건을 정합니다.','')][:n]
   return '<div class="journey" DATA>'+''.join('<div class="stage'+(' on'if i==n-1 else'')+'" style="--mood:'+str(v)+(' ;--next:'+str(stages[i+1][1])if i<n-1 else'')+'"><p class="name">'+name+'</p><p class="note">'+note+'</p>'+('<p class="pain">'+pain+'</p>'if pain else'')+'</div>'for i,(name,v,note,pain) in enumerate(stages))+'</div>'
  write(k,'journey',css,'Operational stages own a continuous emotion curve above their touchpoint notes. A single accent dot marks the decisive step; compact rows remove secondary pain text while retaining stage names and touchpoints.',[('three-touchpoints','6x4',row(3)),('six-touchpoints','8x6',row(6))])
 else:raise SystemExit(k)
if __name__=='__main__':author(sys.argv[1])
